// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 deposit, uint256 minSum, uint256 withdrawAmt) public {
        vm.assume(caller != address(0));
        vm.assume(withdrawAmt > 0);
        vm.assume(deposit >= withdrawAmt);

        // Initialize the contract if not already
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit funds
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        uint256 balanceBefore = c.balances(caller);

        // Try to collect
        vm.prank(caller);
        c.Collect(withdrawAmt);

        uint256 balanceAfter = c.balances(caller);

        // General rule: after Collect, the caller's balance is either unchanged (if conditions not met)
        // or reduced by at most withdrawAmt (original behavior). It should NOT become 0 unless
        // withdrawAmt == balanceBefore (i.e., they withdrew everything)
        if (balanceBefore >= minSum && balanceBefore >= withdrawAmt) {
            assertTrue(balanceAfter == balanceBefore - withdrawAmt || balanceAfter == balanceBefore);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

