pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1234);
    address bob = address(0x5678);

    function setUp() public { 
        c = new C();
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(uint256 depositAlice, uint256 depositBob, uint256 collectAmount) public {
        // Bound inputs to avoid overflow
        vm.assume(depositAlice <= type(uint128).max);
        vm.assume(depositBob <= type(uint128).max);
        vm.assume(collectAmount <= type(uint128).max);

        // Give both users Ether
        vm.deal(alice, depositAlice + collectAmount);
        vm.deal(bob, depositBob);

        // Alice and Bob deposit
        vm.prank(alice);
        c.Deposit{value: depositAlice}();
        vm.prank(bob);
        c.Deposit{value: depositBob}();

        // Record sum of balances before Collect
        uint sumBefore = c.balances(alice) + c.balances(bob);

        // Alice calls Collect
        vm.prank(alice);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // Ensure call succeeded (balances >= MinSum and >= _am)
        vm.assume(ok);

        // Sum after Collect
        uint sumAfter = c.balances(alice) + c.balances(bob);

        // The sum of balances should never increase after Collect
        assertTrue(sumAfter <= sumBefore);
    }
}

