pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _am1, uint256 _deposit1) public {
        // Constrain values to avoid overflow/abort
        vm.assume(_val > 0 && _val < type(uint256).max / 2);
        vm.assume(_am1 > 0 && _am1 <= _val);
        vm.assume(_deposit1 > 0 && _deposit1 <= 1e30);

        // Set MinSum
        c.SetMinSum(_val);
        c.Initialized();

        // Fund the caller
        address caller = address(this);
        vm.deal(caller, _deposit1);

        // Deposit
        c.Deposit{value: _deposit1}();

        // Record balance before Collect
        uint256 balBefore = c.balances(caller);
        require(balBefore >= _am1, "balance insufficient");

        // Call Collect
        c.Collect(_am1);

        // Check: balances[caller] == balBefore - _am1
        assertTrue(c.balances(caller) == balBefore - _am1, "balance after Collect is not correct");
    }
}

