pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 claimAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount <= type(uint256).max - c.balances(caller)); // prevent overflow in deposit
        vm.assume(claimAmount <= depositAmount); // ensure claimable amount does not exceed balance
        vm.assume(minSum > 0); // avoid trivial case where MinSum=0

        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit funds as the caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, claimAmount));

        // Only assert if the call succeeded (i.e., the condition balances[caller] >= MinSum && balances[caller] >= _am was met)
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore - claimAmount, "Balance not decreased by exactly claim amount");
        }
    }
}

