pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        // Bound amounts to avoid overflow in deposit
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 1, 1e18);

        // Initialize with MinSum = 1 so Collect can succeed
        c.SetMinSum(1);
        c.SetLogFile(address(0x1234));
        c.Initialized();

        // Fund sender and deposit
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Record total balance before Collect
        uint256 totalBefore = address(c).balance + c.balances(sender);

        // Call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Record total balance after Collect
        uint256 totalAfter = address(c).balance + c.balances(sender);

        // If Collect reverted, total should be unchanged
        if (!success) {
            assertTrue(totalAfter == totalBefore, "Total decreased on revert");
        } else {
            // If success, total should not decrease
            assertTrue(totalAfter >= totalBefore, "Total decreased after Collect");
        }
    }
}

