pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user1, address user2, uint256 deposit1, uint256 deposit2, uint256 minSum, uint256 collectAmt) public {
        // Restrict inputs: assume users are distinct and not zero
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);
        vm.assume(deposit1 <= 1e18 && deposit2 <= 1e18);
        vm.assume(minSum <= 1e18 && collectAmt <= 1e18);

        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit from two users
        vm.deal(user1, deposit1);
        vm.prank(user1);
        c.Deposit{value: deposit1}();

        vm.deal(user2, deposit2);
        vm.prank(user2);
        c.Deposit{value: deposit2}();

        // Record balances before Collect
        uint256 bal1_before = c.balances(user1);
        uint256 bal2_before = c.balances(user2);

        // Try collect from user1
        vm.prank(user1);
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Check balances after
        uint256 bal1_after = c.balances(user1);
        uint256 bal2_after = c.balances(user2);

        // General rule: sum of all balances should never increase due to Collect
        // In reference: after collect, total balance sum is <= original sum (if not reverted)
        // or unchanged (if reverted). Mutant can cause decrease then increase?
        // Simpler invariant: user's balance after collect <= balance before collect
        // BUT the bug causes balance to increase (since -= in deposit) so after deposit, balance is lower, then collect can happen?
        // Better rule: The total ether in contract is exactly sum(balances) + (ether sent via collect not yet transferred)
        // Let's use: If collect succeeds, then the caller's balance decreases by exactly collectAmt
        if (!reverted) {
            assertTrue(bal1_after == bal1_before - collectAmt, "Collect should decrease caller's balance by exact amount");
        } else {
            assertTrue(bal1_after == bal1_before && bal2_after == bal2_before, "Reverted collect leaves all balances unchanged");
        }
    }
}

