pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();
    }

    function testFuzz_property(address caller, address other, uint256 depositAmount, uint256 collectAmount, uint256 otherDeposit, uint256 otherCollect) public {
        // Restrict inputs to avoid overflow issues
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 0, depositAmount);
        otherDeposit = bound(otherDeposit, 0, 1e18);
        otherCollect = bound(otherCollect, 0, otherDeposit);
        vm.assume(caller != address(0) && other != address(0) && caller != other);

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Deposit from other
        if (otherDeposit > 0) {
            vm.deal(other, otherDeposit);
            vm.prank(other);
            c.Deposit{value: otherDeposit}();
        }

        // Record caller's balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect from caller
        vm.deal(caller, 0); // Ensure caller has ETH to receive
        vm.prank(caller);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After Collect, caller's balance must be exactly balanceBefore - collectAmount (if no revert)
        uint256 balanceAfter = c.balances(caller);

        if (success && collectAmount <= balanceBefore) {
            // Rule: balance must decrease by exactly collectAmount
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance change incorrect");
        } else {
            // If Collect reverted or was skipped, balances unchanged
            assertTrue(balanceAfter == balanceBefore, "Balance should not change");
        }
    }
}

