pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint amount, uint sumBefore, uint sumAfter) public {
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.assume(sumBefore <= type(uint256).max / 2);
        vm.assume(sumAfter <= type(uint256).max / 2);

        // Set up minimal deposit and collect
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Prepare caller with ether
        vm.deal(caller, amount);

        // Deposit into contract
        vm.prank(caller);
        c.Deposit{value: amount}();

        // Record balance of caller before collect
        uint callerBalanceBefore = c.balances(caller);

        // Simulate collect with sumBefore and sumAfter as unrelated values
        // The key is to check that caller's balance does not increase
        try c.Collect(amount) {
            // Collect succeeded — caller's balance should decrease by amount
            uint callerBalanceAfter = c.balances(caller);
            assertTrue(callerBalanceAfter <= callerBalanceBefore);
        } catch {
            // Collect reverted — caller's balance must remain unchanged
            uint callerBalanceAfter = c.balances(caller);
            assertTrue(callerBalanceAfter == callerBalanceBefore);
        }
    }
}

