import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 minSum, uint256 deposit1, uint256 deposit2) public {
        vm.assume(sender != address(0));
        minSum = bound(minSum, 0, 1e18);
        deposit1 = bound(deposit1, 0, 1e18);
        deposit2 = bound(deposit2, 0, 1e18);
        c.SetMinSum(minSum);
