        vm.deal(sender, deposit1 + deposit2);
        vm.prank(sender);
        c.Deposit{value: deposit1}();
        vm.prank(sender);
        c.Deposit{value: deposit2}();
        uint256 totalDeposits = deposit1 + deposit2;
        uint256 balanceBefore = c.balances(sender);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", balanceBefore));
        if (success) {
            uint256 balanceAfter = c.balances(sender);
            uint256 totalEtherReceived = totalDeposits;
            uint256 totalEtherSent = balanceBefore; // since we collected full balance
            uint256 sumBalances = c.balances(sender);
            assertTrue(sumBalances <= totalEtherReceived - totalEtherSent + 1e-9); // allow rounding but basically sum <= net deposits - net collects
        } else {
            assertTrue(true);
        }
    }
}

