pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _setMinSumVal, uint256 _collectAm, uint256 _depositVal) public {
        // Restrict inputs to avoid overflow/revert edge cases
        vm.assume(_depositVal < type(uint256).max / 2);
        vm.assume(_collectAm < type(uint256).max / 2);
        vm.assume(_setMinSumVal <= type(uint256).max / 2);

        // Step 0: Initial deposit to have balance
        vm.deal(address(this), _depositVal);
        c.Deposit{value: _depositVal}();

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Step 1: Call SetMinSum (if allowed) – in reference it sets MinSum, in mutant it does nothing
        c.SetMinSum(_setMinSumVal);

        // Step 2: Call Initialized() to prevent further SetMinSum
        c.Initialized();

        // Step 3: Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collectAm));

        // Rule: After Collect, MinSum must equal either the value set in SetMinSum (if it was called) or the value before.
        // Since Initialized() locks further SetMinSum, the value after SetMinSum call is either _setMinSumVal (reference) or 0 (mutant).
        // The reference: SetMinSum(_setMinSumVal) sets MinSum to _setMinSumVal before Initialized, so after Collect, MinSum == _setMinSumVal.
        // The mutant: SetMinSum does nothing, so MinSum remains as before (0 due to initial default).
        // Thus the rule: c.MinSum() == minSumBefore (which is 0) or c.MinSum() == _setMinSumVal, but the reference always yields _setMinSumVal.
        // To be invariant for reference, we assert that after Collect, MinSum == _setMinSumVal.
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == _setMinSumVal, "MinSum should equal the last value sent to SetMinSum");
    }
}

