pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 deposit, uint256 collectAmt) public {
        // Precondition: make deposit and minSum reasonable
        vm.assume(deposit > 0 && deposit < 1e30);
        vm.assume(collectAmt <= deposit);
        vm.assume(minSum <= type(uint256).max);

        // Setup: fund contract and deposit for msg.sender
        address user = address(0x1234);
        vm.deal(user, deposit);
        vm.prank(user);
        c.Deposit{value: deposit}();

        // Set MinSum (can be any value)
        c.SetMinSum(minSum);
        c.Initialized();

        // Now try Collect (may revert if MinSum > deposit)
        // We call Collect with the user
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // After Collect, MinSum must equal minSum (rule: Collect does not change MinSum)
        uint256 currentMinSum = c.MinSum();
        assertTrue(currentMinSum == minSum);
    }
}

