        if (success) {
            uint256 balanceAfter = c.balances(caller);
            uint256 contractBalanceAfter = address(c).balance;
            // Invariant: total ether (balance + contract balance) should not increase
            // Original: (balanceBefore + contractBalanceBefore) = total deposits
            // After collect: balanceAfter + contractBalanceAfter should be <= total deposits + extra (if double deposit bug)
