        uint256 deposit = bound(uint256(keccak256(abi.encode(caller, 1))), 0, 100 ether);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead)); // Dummy log file
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, deposit + am);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Record balance before Collect
        uint256 callerContractBalanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Record balance after Collect
        uint256 callerContractBalanceAfter = c.balances(caller);

        // Rule: If caller’s balance < minSum, Collect should revert and balance unchanged
        // If caller’s balance >= minSum, balance decreases by at most am (if success) or unchanged (if revert)
        bool condition = (callerContractBalanceBefore >= minSum);
        if (!condition) {
            // Collect should revert due to condition failing; balance unchanged
            assertTrue(!success);
            assertTrue(callerContractBalanceAfter == callerContractBalanceBefore);
        } else {
            // Condition holds; Collect may succeed or fail due to transfer to caller
            if (success) {
                // Balance decreases by exactly am
                assertTrue(callerContractBalanceAfter == callerContractBalanceBefore - am);
            } else {
                assertTrue(callerContractBalanceAfter == callerContractBalanceBefore);
            }
        }
    }
}

