        vm.prank(address(this));
        c.Deposit{value: depositAmount}();

        // Now try to collect with the test contract as msg.sender
        vm.prank(address(this));
        (bool success, bytes memory data) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalanceAfter = c.balances(address(this));

