contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 initialBalance) public {
        vm.assume(_am > 0 && _am <= type(uint256).max / 2);
        vm.assume(initialBalance >= _am && initialBalance <= type(uint256).max / 2);
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
        address user = address(0x1234);
        vm.deal(user, initialBalance);
        vm.prank(user);
        c.Deposit{value: initialBalance}();
        LogFile logFile = LogFile(c.Log());
        uint256 lenBefore = logFile.History.length();
        vm.prank(user);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _am));
